INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63645886', 63645886, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Layanan Wifi Gratis Kota Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Mojokerto (Kota)', 690179783, 'December 2025', 'APBD', 1, 1, '1 Paket;', 'Internet Broadband Up to 20Mbps', 'Internet Broadband Up to 20Mbps Dengan Rincian : Spesifikasi Teknis: 1. Menyediakan Internet Broadband Up to 20 Mbps dengan media komunikasi fiber optik sebanyak 410 titik Wifi Gratis dengan spesifikasi teknis : I. Pemakaian dengan infrastruktur penyedia : a. Kuota Unlimited Non FUP (Fair Usage Policy), tidak ada batasan kuota pemakaian; b. SSID (Service Set Identifier) / nama WiFi dapat dimodifikasi sesuai permintaan Dinas Komunikasi dan Informatika; c. Non SLA (Service Level Agreement); d. Menyediaan Modem ONT Dual Band yang sudah tersertifikasi POSTEL pada setiap titik sebanyak 236; e. Pemasangan seluruh modem ONT Dual Band sebanyak 236 titik selesai dilaksanakan paling lambat bulan April 2026; f. Support dengan ekosistem Mikrotik; g. Menyediakan akses monitoring The Dude Mikrotik untuk Dinas Komunikasi dan Informatika Kota Mojokerto; II. Pemakaian dengan infrastruktur Pemerintah Kota Mojokerto: a. Menyediakan bandwidth broadband sebanyak 174 titik dikali up to 20 Mbps; b. Menyediakan pinjam pakai Router Mikrotik CCR2116-12G-4S+ sebanyak 1 unit selama masa berlaku Surat Pesanan (SP); c. Kuota Unlimited Non FUP (Fair Usage Policy), tidak ada batasan kuota pemakaian; d. Non SLA (Service Level Agreement); 2. Menyediakan support layanan 24jam*7 hari selama masa berlaku SP melalui contact service berupa no telp, email atau whatsapp, sistem trouble ticketing dan eskalasi maksimal 3 (tiga) jam respon untuk pengaduan gangguan dari PIC yang di tunjuk oleh Dinas Komunikasi dan informatika Kota Mojokerto; 3. Penyelesaian gangguan maksimal 3x24 Jam; 4. Menyediakan sticker yang berisi informasi bahwa area tersebut terdapat layanan wifi gratis dari Pemerintah Kota Mojokerto; Spesifikasi tambahan: 1. Sudah memiliki izin penggunaan Ruang Milik Jalan (RUMIJA) yang masih berlaku atau sudah melakukan Perjanjian Kerja Sama dengan Pemerintah Kota Mojokerto atau sudah melakukan pembayaran sewa Ruang Milik Jalan (RUMIJA). 2. Apabila pada spesifikasi tambahan poin 1 belum terpenuhi, maka dapat menggunakan bukti dokumen kegiatan perizinan penggunaan Ruang Milik Jalan (RUMIJA) yang sedang berproses. 3. Telah terdaftar sebagai penyedia layanan telekomunikasi di Kementrian Komunikasi dan Digital.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1060341);
