INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63648743', 63648743, 'analyze_legacy', 'Kejaksaan Republik Indonesia', 'central', 'CABANG KEJAKSAAN NEGERI TOLI TOLI DI OGOTUA', 'Pengadaan Outsourcing Cabang Kejaksaan Negeri Toli-Toli di Ogotua Tahun 2026', 'Barang', 'E-Purchasing', 'Sulawesi Tengah, Toli-Toli (Kab.)', 423912000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Outsourcing Cabang Kejaksaan Negeri Toli-Toli di Ogotua Tahun 2026 Berjumlah 8 org dengan rincian sebagai berikut : Pengawas 1 org Pramubakti 1 org Tenaga Kebersihan 2 org Petugas PTSP 1 org Satpam 3 org', 'Umum: WNI, usia minimal 18 tahun dan maksimal 50 tahun (kecuali ditentukan lain), sehat jasmani dan rohani, serta berkelakuan baik. Khusus Pengawas : Pengalaman minimal 1 tahun sebagai koordinator lapangan atau supervisor outsourcing. Memiliki jiwa kepemimpinan yang tegas namun komunikatif. Wajib menguasai MS Office (Word & Excel) untuk penyusunan laporan dan pengiriman email. Pendidikan minimal D3/S1 (lebih diutamakan untuk memudahkan koordinasi administratif). Khusus Satpam: Wajib memiliki minimal sertifikat Gada Pratama dan KTA yang masih aktif. Khusus PTSP: Berpenampilan menarik (good looking), komunikatif, dan menguasai penggunaan komputer dasar. Khusus Driver : Bebas narkoba dan miras (dibuktikan dengan surat keterangan). Tidak memiliki catatan kriminal. Memahami rute jalan di wilayah Sulawesi Tengah dan sekitarnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1061759);
