INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63626170', 63626170, 'analyze_legacy', 'Badan Nasional Pencarian dan Pertolongan', 'central', 'Badan Nasional Pencarian dan Pertolongan', 'Penyusunan Repair List Kapal Basarnas', 'Jasa Konsultansi', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1350000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Set', 'Pekerjaan penyusunan repairlist ini adalah tersusunnya dokumen spesifikasi teknis, engineering estimate, dan rencana anggaran biaya docking kapal sesuai data dan informasi dari lapangan yang dapat dipertanggungjawabkan', 'Lingkup pekerjaan penyusunan repair list adalah sebagai berikut: 1) Melaksanakan survei kondisi masing-masing kapal langsung di lokasi untuk mengetahui kondisi eksisting kapal; 2) Mengidentifikasi, mencatat dan mendokumentasikan setiap bagian yang dimasukkan dalam repair list sesuai data repair list dari Kantor Pencarian dan Pertolongan dan/atau kondisi eksisting pada saat dilaksanakan survei; 3) Mengumpulkan data dan/atau dokumen rujukan harga bahan, upah dan sewa peralatan yang berlaku di lokasi docking terdekat dengan tempat sandar kapal; 4) Membuat analisis harga satuan untuk setiap item pekerjaan yang ada pada kegiatan tersebut; 5) Mengidentifikasi dengan cermat semua item pekerjaan yang diperlukan dan menghitung volume dari setiap item pekerjaan, guna menyusun Engineer Estimate (EE) untuk Rencana Anggaran Biaya (RAB); 6) Menyusun spesifikasi teknis dari asumsi urutan atau tahap pekerjaan yang dilakukan pada setiap kegiatan pembongkaran dan pemasangan ulang barang/material yang diperbaiki atau diganti pada setiap item repair list; 7) Membuat Engineer Estimate (EE) berdasarkan analisis mendalam terhadap berbagai faktor teknis, seperti bahan/ material, tenaga kerja, peralatan, dan lain-lain yang diperlukan untuk menyelesaikan pekerjaan docking kapal; 8) Menyusun rencana anggaran biaya (RAB) sesuai perhitungan Engineer Estimate (EE); 9) Membuat estimasi kebutuhan waktu pelaksanaan masing-masing pekerjan docking kapal;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1062854);
