INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63604920', 63604920, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Honorarium Tenaga Alih Daya Biro Humas (Outsourcing)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 1343433000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Paket pekerjaan ini mencakup penyediaan dan pembayaran honorarium tenaga alih daya untuk mendukung operasional Biro Humas, meliputi layanan driver (pengemudian dan dukungan mobilitas kedinasan), petugas kebersihan (kebersihan dan pemeliharaan area kerja), serta pramubakti (dukungan layanan perkantoran dan kegiatan), sesuai kebutuhan dan penugasan yang ditetapkan oleh penanggung jawab.', 'A. Jenis Pekerjaan : Jasa penyediaan tenaga alih daya (outsourcing) untuk mendukung operasional Biro Humas. B. Lingkup Tenaga Alih Daya : Driver; Petugas Kebersihan; Pramubakti C. Kualifikasi Umum Tenaga Alih Daya 1. Sehat jasmani dan rohani. 2. Berperilaku baik, disiplin, dan bertanggung jawab. 3. Mampu bekerja sesuai arahan dan kebutuhan operasional. 4. Mematuhi ketentuan tata tertib dan standar layanan di lingkungan kerja. D. Standar Pelaksanaan Pekerjaan 1. Pekerjaan dilaksanakan sesuai jadwal dan kebutuhan kegiatan. 2. Tenaga alih daya bekerja di bawah koordinasi dan pengawasan penanggung jawab kegiatan. 3. Pelaksanaan pekerjaan mengutamakan ketertiban, keamanan, dan kenyamanan lingkungan kerja. E. Output Pekerjaan 1. Terpenuhinya kebutuhan layanan driver, kebersihan, dan pramubakti. 2. Terjaganya kelancaran operasional dan aktivitas perkantoran Biro Humas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1063935);
