INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63607872', 63607872, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI PENGELOLA TRANSPORTASI DARAT KELAS II PAPUA', 'Belanja Pemeliharaan Peralatan dan Mesin', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 16000000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Belanja Pemeliharaan Peralatan dan Mesin ( 1, Tahun, @ 14000000 ); 2. Peralatan Penunjang Data dan Infrormasi ( 1, Tahun, @ 2000000 );', 'Siap 👍 berikut contoh Spesifikasi Pekerjaan yang bisa langsung kamu input di SIRUP. Spesifikasi Pekerjaan 1. Belanja Pemeliharaan Peralatan dan Mesin (1 Tahun, @ Rp14.000.000) Pengadaan jasa/biaya pemeliharaan peralatan dan mesin untuk mendukung kelancaran operasional perkantoran selama 1 (satu) tahun anggaran. Ruang lingkup pekerjaan meliputi: Pemeliharaan rutin dan berkala peralatan kantor dan mesin; Pemeriksaan, pembersihan, dan penyetelan peralatan; Penggantian suku cadang ringan/komponen kecil yang mengalami keausan; Perbaikan ringan apabila terjadi gangguan fungsi; Pengujian kembali untuk memastikan peralatan berfungsi dengan baik. Ketentuan: Pemeliharaan dilakukan secara berkala atau sesuai kebutuhan; Suku cadang yang digunakan harus baru dan sesuai spesifikasi pabrikan; Tidak termasuk penggantian unit baru (bukan belanja modal); Hasil pekerjaan harus menjamin peralatan kembali berfungsi optimal. 2. Peralatan Penunjang Data dan Informasi (1 Tahun, @ Rp2.000.000) Pengadaan peralatan penunjang data dan informasi untuk mendukung kegiatan administrasi dan pengelolaan data selama 1 (satu) tahun anggaran. Ruang lingkup pengadaan meliputi: Perangkat pendukung komputer seperti mouse, keyboard, flashdisk, kabel data, adaptor, atau perangkat pendukung lainnya; Media penyimpanan data; Perlengkapan kecil pendukung jaringan/informasi. Ketentuan: Barang harus baru, layak pakai, dan sesuai standar teknis; Memiliki garansi sesuai ketentuan pabrikan (jika berlaku); Spesifikasi disesuaikan dengan kebutuhan operasional satuan kerja; Tidak termasuk pengadaan perangkat utama bernilai kapitalisasi (bukan belanja modal besar).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1068734);
